Before:

```
#include <metal_stdlib>
using namespace metal;
kernel void E_32768_32_4(device float* data0, const device float* data1, uint3 gid [[threadgroup_position_in_grid]], uint3 lid [[thread_position_in_threadgroup]]) {
{ int gidx0 = gid.x;  /* 32768 */
  { int lidx1 = lid.x;  /* 32 */
    float4 val1_0 = (float4)(((device float4*)data1)[((gidx0*32)+lidx1)]);
    float val2_0 = 1.0f;
    float alu0 = (val1_0.x+val2_0);
    float alu1 = (val1_0.y+val2_0);
    float alu2 = (val1_0.z+val2_0);
    float alu3 = (val1_0.w+val2_0);
    float4 alu4 = float4(alu0,alu1,alu2,alu3);
    ((device float4*)data0)[((gidx0*32)+lidx1)] = alu4;
  }} /* global+local */
}
```

After:

```
#include <metal_stdlib>
using namespace metal;
kernel void E_32768_32_4(device float* data0, const device float* data1, uint3 gid [[threadgroup_position_in_grid]], uint3 lid [[thread_position_in_threadgroup]]) {
{ int gidx0 = gid.x;  /* 32768 */
  { int lidx1 = lid.x;  /* 32 */
    float4 val1_0 = (float4)(((device float4*)data1)[((gidx0*32)+lidx1)]);
    float val2_0 = 1.0f;
    float4 alu0 = (val2_0+val1_0);
    ((device float4*)data0)[((gidx0*32)+lidx1)] = alu0;
  }} /* global+local */
}
```

## Description

Currently, the codemod fails to move the signature "outside" when the component has already passed a valid signature.

```ts
import templateOnlyComponent from '@ember/component/template-only';

type MenuItem = {
  label: string;
  route: string;
};

/* The input code remains the same */
const NavigationMenuComponent = templateOnlyComponent<{
  Args: {
    menuItems: MenuItem[];
    name?: string;
  };
}>();

export default NavigationMenuComponent;

declare module '@glint/environment-ember-loose/registry' {
  export default interface Registry {
    NavigationMenu: typeof NavigationMenuComponent;
  }
}
```

I updated `create-signatures` so that we will have instead,

```ts
import templateOnlyComponent from '@ember/component/template-only';

type MenuItem = {
  label: string;
  route: string;
};

interface NavigationMenuSignature {
  Args: {
    menuItems: MenuItem[];
    name?: string;
  };
}

const NavigationMenuComponent = templateOnlyComponent<NavigationMenuSignature>();

export default NavigationMenuComponent;

declare module '@glint/environment-ember-loose/registry' {
  export default interface Registry {
    NavigationMenu: typeof NavigationMenuComponent;
  }
}
```

**This is a feature branch of the [fix/bandwidth](https://github.com/hellostealth/stealth/tree/fix/bandwidth) branch**

The PR adds an optional 'slice' argument to the `handle_message` and `get_match` methods with a default value of `true` to automatically slice any text message content after a line break (i.e. assuming that the presence of a line break is for an SMS/text message signature).

To disable it, we need to explicitly pass the argument with a `false` value to the methods

```
handle_message(
  false,
  :yes => proc {
    puts 'Yes'
  },
  :no => proc {
    puts 'No'
  }
)

get_match(
  [
   'Yes',
   'No',
   'Maybe'
  ], slice: false
)
```

